import React, { useState } from 'react';
import './TentsPage.css';

const TentsPage = () => {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [showApplications, setShowApplications] = useState(false);
  const [showTechSpecs, setShowTechSpecs] = useState(false);
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [selectedPdf, setSelectedPdf] = useState(null);

  const categories = [
    { name: "PAGODAS", id: 1 },
    { name: "PYRAMIDS", id: 2 },
    { name: "A-SHAPED", id: 3 },
    { name: "ALUMINIUM", id: 4 }
  ];

  const applications = [
    { name: "Weddings", id: 1 },
    { name: "Outdoor caterings", id: 2 },
    { name: "Events", id: 3 },
    { name: "Exhibitions", id: 4 },
    { name: "Parties", id: 5 },
    { name: "Events/Large gatherings", id: 6 },
    { name: "Labour/Military/Medical Camps", id: 7 }
  ];

  const handleCategoryClick = (category) => {
    setSelectedCategory(category);
    setShowApplications(false);
    setShowTechSpecs(false);
    setSelectedApplication(null);
  };

  const handleApplicationsClick = () => {
    setShowApplications(true);
    setShowTechSpecs(false);
    setSelectedApplication(null);
  };

  const handleTechSpecsClick = () => {
    setShowTechSpecs(true);
    setShowApplications(false);
    setSelectedApplication(null);
  };

  const handleApplicationClick = (application) => {
    setSelectedApplication(application);
  };

  const handlePdfClick = (size, coneType) => {
    const pdfName = `${coneType.toLowerCase().replace(' ', '-')}-${size}.pdf`;
    setSelectedPdf({ size, coneType, pdfName });
  };

  if (selectedCategory) {
    return (
      <div className="tents-page selected-view">
        <div className="sidebar">
          <div className="sidebar-top">
            <button className="category-pill selected">
              {selectedCategory.name}
            </button>
            <div className="sidebar-pills">
              <button className="category-pill" onClick={handleApplicationsClick}>Applications</button>
              <button className="category-pill" onClick={handleTechSpecsClick}>Tech Specs</button>
            </div>
          </div>
          {showApplications && (
            <div className="applications-list">
              {applications.map((app) => (
                <button 
                  key={app.id} 
                  className="application-item"
                  onClick={() => handleApplicationClick(app)}
                >
                  {app.name}
                </button>
              ))}
            </div>
          )}
          {showTechSpecs && (
            <div className="tech-specs-table">
              <table>
                <thead>
                  <tr>
                    <th>Single Cone</th>
                    <th>Double Cone</th>
                    <th>Triple Cone</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td onClick={() => handlePdfClick('10x10', 'Single Cone')}>10x10</td>
                    <td onClick={() => handlePdfClick('10x20', 'Double Cone')}>10x20</td>
                    <td onClick={() => handlePdfClick('10x30', 'Triple Cone')}>10x30</td>
                  </tr>
                  <tr>
                    <td onClick={() => handlePdfClick('10x15', 'Single Cone')}>10x15</td>
                    <td onClick={() => handlePdfClick('10x30', 'Double Cone')}>10x30</td>
                    <td onClick={() => handlePdfClick('10x45', 'Triple Cone')}>10x45</td>
                  </tr>
                  <tr>
                    <td onClick={() => handlePdfClick('10x20', 'Single Cone')}>10x20</td>
                    <td onClick={() => handlePdfClick('10x40', 'Double Cone')}>10x40</td>
                    <td onClick={() => handlePdfClick('10x60', 'Triple Cone')}>10x60</td>
                  </tr>
                  <tr>
                    <td onClick={() => handlePdfClick('15x15', 'Single Cone')}>15x15</td>
                    <td onClick={() => handlePdfClick('15x30', 'Double Cone')}>15x30</td>
                    <td onClick={() => handlePdfClick('15x45', 'Triple Cone')}>15x45</td>
                  </tr>
                  <tr>
                    <td onClick={() => handlePdfClick('15x20', 'Single Cone')}>15x20</td>
                    <td onClick={() => handlePdfClick('15x40', 'Double Cone')}>15x40</td>
                    <td onClick={() => handlePdfClick('15x60', 'Triple Cone')}>15x60</td>
                  </tr>
                  <tr>
                    <td onClick={() => handlePdfClick('20x20', 'Single Cone')}>20x20</td>
                    <td onClick={() => handlePdfClick('20x40', 'Double Cone')}>20x40</td>
                    <td onClick={() => handlePdfClick('20x60', 'Triple Cone')}>20x60</td>
                  </tr>
                </tbody>
              </table>
            </div>
          )}
        </div>
        <div className="content-area">
          {selectedPdf ? (
            <div className="pdf-viewer">
              <h3>{selectedPdf.coneType} - {selectedPdf.size}</h3>
              <iframe 
                src={`/pdfs/${selectedPdf.pdfName}`}
                width="100%"
                height="90%"
                title={`${selectedPdf.coneType} ${selectedPdf.size} Specifications`}
              >
                <p>Your browser does not support PDFs. <a href={`/pdfs/${selectedPdf.pdfName}`}>Download the PDF</a>.</p>
              </iframe>
            </div>
          ) : selectedApplication ? (
            <div className="image-gallery">
              <div className="top-images">
                <div className="image-placeholder">Image 1 - {selectedApplication.name}</div>
                <div className="image-placeholder">Image 2 - {selectedApplication.name}</div>
              </div>
              <div className="bottom-image">
                <div className="image-placeholder">Image 3 - {selectedApplication.name}</div>
              </div>
            </div>
          ) : (
            <div>
              <h2>{selectedCategory.name} Content</h2>
              <p>Content for {selectedCategory.name} will be displayed here.</p>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="tents-page">
      <div className="disclaimer">
        For custom tents, kindly contact us
      </div>
      <div className="quadrants-grid">
        {categories.map((category) => (
          <div key={category.id} className="quadrant">
            <button 
              className="category-pill"
              onClick={() => handleCategoryClick(category)}
            >
              {category.name}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TentsPage;
